/**
 * parameterRender.ts — helpers that turn the bundled n8n node schema +
 * a runtime parameters object into the data the NodeParameterPanel
 * Svelte component renders. Pure functions only — no Svelte imports —
 * so they unit-test cleanly.
 *
 * The schema comes from `nodeSchemaManifest.ts` (autogenerated by
 * `scripts/bundle-n8n-schemas.ts` from the compiled n8n custom-node
 * classes). The runtime values come from the workflow JSON's per-node
 * `parameters` blob.
 *
 * Built-in n8n nodes (`n8n-nodes-base.*`) are not in the manifest;
 * callers fall back to a value-only renderer for those.
 */

import type { ParamProperty, NodeSchema } from './nodeSchemaManifest';
import { schemaFor } from './nodeSchemaManifest';

export type { ParamProperty, NodeSchema };

/** Look up the schema for an n8n node type, or `undefined` if unknown. */
export function resolveSchema(nodeType: string): NodeSchema | undefined {
  return schemaFor(nodeType);
}

/**
 * Mirror n8n's own visibility rules. A property's `displayOptions.show`
 * declares "render me only when ALL of these other parameters currently
 * hold one of the listed values"; `displayOptions.hide` is the inverse.
 *
 * When the parameter referenced by show/hide is absent from `values`,
 * n8n falls back to the property's declared `default`. We mirror that
 * by passing in `defaultsByName` so a freshly-loaded node without
 * explicit values still hides the right fields.
 */
export function isVisible(
  prop: ParamProperty,
  values: Record<string, unknown>,
  defaultsByName: Record<string, unknown>,
): boolean {
  const opts = prop.displayOptions;
  if (!opts) return true;
  const lookup = (key: string): unknown => {
    if (key in values) return values[key];
    if (key in defaultsByName) return defaultsByName[key];
    return undefined;
  };
  if (opts.show) {
    for (const [key, allowed] of Object.entries(opts.show)) {
      const v = lookup(key);
      if (!Array.isArray(allowed) || !allowed.includes(v as never)) return false;
    }
  }
  if (opts.hide) {
    for (const [key, blocked] of Object.entries(opts.hide)) {
      const v = lookup(key);
      if (Array.isArray(blocked) && blocked.includes(v as never)) return false;
    }
  }
  return true;
}

/** Build a `name -> default` map for `isVisible` lookups. */
export function defaultsFor(properties: readonly ParamProperty[]): Record<string, unknown> {
  const out: Record<string, unknown> = {};
  for (const p of properties) out[p.name] = p.default;
  return out;
}

/** Filter a property list down to what should currently be visible. */
export function visibleProperties(
  properties: readonly ParamProperty[],
  values: Record<string, unknown>,
): ParamProperty[] {
  const defaults = defaultsFor(properties);
  return properties.filter((p) => isVisible(p, values, defaults));
}

/**
 * For `options` / `multiOptions` types, n8n stores the raw `value` in
 * the runtime parameters blob. Render the human-readable `name` (with
 * the raw value as a tooltip-style suffix when they differ).
 */
export function optionLabel(prop: ParamProperty, value: unknown): string {
  if (!prop.options || prop.options.length === 0) return String(value);
  const match = prop.options.find((o) => o.value === value);
  if (!match) return String(value);
  return match.name;
}

/**
 * Render a multi-options value (array of raw values) as a comma-joined
 * list of option names, in the order they appear in `values`.
 */
export function multiOptionLabels(prop: ParamProperty, values: unknown): string[] {
  if (!Array.isArray(values)) return [];
  return values.map((v) => optionLabel(prop, v));
}

/**
 * Long-ish string detector. Used by the panel to switch from an inline
 * <span> to a <pre> block so multi-line values (Code-node `jsCode`,
 * HTML/SQL editors, prose-y descriptions) render readably instead of
 * collapsing newlines into a single line.
 */
export function isLongString(v: unknown, threshold = 80): boolean {
  return typeof v === 'string' && (v.includes('\n') || v.length > threshold);
}

/**
 * Heuristic stringifier for "everything else" — used inside the
 * value-only fallback renderer for built-in nodes (no schema), and
 * for primitive types in the schema-aware path.
 */
export function formatScalar(v: unknown): string {
  if (v === null || v === undefined || v === '') return '—';
  if (typeof v === 'boolean') return v ? 'Yes' : 'No';
  if (typeof v === 'number') return String(v);
  if (typeof v === 'string') return v;
  return JSON.stringify(v);
}

/**
 * Sorted alphabetical key/value rendering used when no schema is
 * available (built-in n8n-nodes-base.* or anything else not bundled).
 * Returns an array of `[displayName, formattedValue]` rows.
 */
export function valueOnlyRows(parameters: Record<string, unknown>): Array<[string, string]> {
  const keys = Object.keys(parameters).sort();
  return keys.map((k) => [k, formatScalar(parameters[k])]);
}
